package com.mallcloud.seckill.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.mallcloud.api.message.*; import com.mallcloud.common.error.*; import com.mallcloud.seckill.dto.*; import com.mallcloud.seckill.entity.SeckillActivityEntity; import com.mallcloud.seckill.mapper.SeckillActivityMapper;
import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.data.redis.core.script.DefaultRedisScript; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.time.*; import java.time.ZoneId; import java.util.*; import java.util.concurrent.TimeUnit;
@Service public class SeckillService {
 private final SeckillActivityMapper activities;private final StringRedisTemplate redis;private final DefaultRedisScript<Long> script;private final RabbitTemplate rabbit;
 public SeckillService(SeckillActivityMapper a,StringRedisTemplate r,DefaultRedisScript<Long>s,RabbitTemplate q){activities=a;redis=r;script=s;rabbit=q;}
 @Transactional public SeckillActivityEntity create(ActivityRequest r){if(!r.endTime().isAfter(r.startTime()))throw new BizException(ErrorCode.BAD_REQUEST,"结束时间必须晚于开始时间");SeckillActivityEntity a=new SeckillActivityEntity();a.setProductId(r.productId());a.setActivityName(r.activityName());a.setSeckillPrice(r.seckillPrice());a.setTotalStock(r.totalStock());a.setLimitPerUser(r.limitPerUser());a.setStartTime(r.startTime());a.setEndTime(r.endTime());a.setStatus(1);a.setCreateTime(LocalDateTime.now());activities.insert(a);preheat(a);return a;}
 public List<SeckillActivityEntity> list(){return activities.selectList(new LambdaQueryWrapper<SeckillActivityEntity>().eq(SeckillActivityEntity::getStatus,1).orderByAsc(SeckillActivityEntity::getStartTime));}
  public SeckillResult attempt(Long activityId,Long userId,SeckillRequest request){SeckillActivityEntity a=activities.selectById(activityId);if(a==null||a.getStatus()!=1)throw new BizException(ErrorCode.NOT_FOUND,"秒杀活动不存在");preheatIfMissing(a);long now=System.currentTimeMillis();ZoneId zone=ZoneId.systemDefault();Long remaining=redis.execute(script,List.of(stockKey(activityId),buyersKey(activityId)),userId.toString(),String.valueOf(now),String.valueOf(a.getStartTime().atZone(zone).toInstant().toEpochMilli()),String.valueOf(a.getEndTime().atZone(zone).toInstant().toEpochMilli()));if(remaining==null||remaining<0){String msg=remaining!=null&&remaining==-3?"每位用户限购一次":remaining!=null&&remaining==-4?"活动尚未开始":remaining!=null&&remaining==-5?"活动已经结束":"商品已抢完";throw new BizException(ErrorCode.SECKILL_FAILED,msg);}String requestNo="SK"+activityId+"-"+userId;SeckillOrderEvent event=new SeckillOrderEvent(UUID.randomUUID().toString(),activityId,userId,a.getProductId(),1,a.getSeckillPrice(),requestNo,request.receiverName(),request.receiverPhone(),request.receiverAddress());redis.opsForValue().set(resultKey(requestNo),"PENDING",1,TimeUnit.DAYS);rabbit.convertAndSend(MqNames.BUSINESS_EXCHANGE,MqNames.SECKILL_ORDER_KEY,event);return new SeckillResult(requestNo,"PENDING",null,"抢购请求已进入队列");}
 public SeckillResult result(String requestNo,Long userId){if(!requestNo.endsWith("-"+userId))throw new BizException(ErrorCode.FORBIDDEN);String value=redis.opsForValue().get(resultKey(requestNo));if(value==null)return new SeckillResult(requestNo,"NOT_FOUND",null,"未找到抢购记录");if(value.startsWith("SUCCESS:"))return new SeckillResult(requestNo,"SUCCESS",value.substring(8),"订单创建成功");return new SeckillResult(requestNo,value,null,"PENDING".equals(value)?"订单正在创建":"订单创建失败，库存已退回");}
 public void preheat(SeckillActivityEntity a){Duration ttl=Duration.between(LocalDateTime.now(),a.getEndTime()).plusDays(1);redis.opsForValue().set(stockKey(a.getId()),a.getTotalStock().toString(),ttl.isNegative()?Duration.ofDays(1):ttl);}
 private void preheatIfMissing(SeckillActivityEntity a){if(Boolean.FALSE.equals(redis.hasKey(stockKey(a.getId()))))preheat(a);}
 public void success(String requestNo,String orderNo){redis.opsForValue().set(resultKey(requestNo),"SUCCESS:"+orderNo,Duration.ofDays(1));}
 public void fail(SeckillOrderEvent e){redis.opsForValue().increment(stockKey(e.activityId()));redis.opsForSet().remove(buyersKey(e.activityId()),e.userId().toString());redis.opsForValue().set(resultKey(e.requestNo()),"FAILED",Duration.ofDays(1));}
 private String stockKey(Long id){return "mall:seckill:stock:"+id;}private String buyersKey(Long id){return "mall:seckill:buyers:"+id;}private String resultKey(String no){return "mall:seckill:result:"+no;}
}
